fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> Option<usize> {
    // Since the array is sorted non-decreasingly, we can use binary search
    // to efficiently find the first occurrence of the target.

    let mut left = 0;
    let mut right = arr.len();

    while left < right {
        let mid = left + (right - left) / 2;
        if arr[mid] < target {
            // Target must be to the right.
            left = mid + 1;
        } else {
            // arr[mid] >= target, so first occurrence could be at mid or to the left
            right = mid;
        }
    }

    // After the loop, left == right is the candidate index of first occurrence
    if left < arr.len() && arr[left] == target {
        Some(left)
    } else {
        None
    }
}